package ca.trailbound.app;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.os.*;
import android.webkit.*;
import androidx.webkit.WebViewAssetLoader;
import java.io.*;
public final class MainActivity extends androidx.activity.ComponentActivity {
 private WebView web;private TrackDb db;private ValueCallback<Uri[]> fileCallback;private String pendingDocument;private String pendingName;private static final String ORIGIN="https://appassets.androidplatform.net";
 public void onCreate(Bundle saved){super.onCreate(saved);db=new TrackDb(this);web=new WebView(this);setContentView(web);getOnBackPressedDispatcher().addCallback(this,new androidx.activity.OnBackPressedCallback(true){public void handleOnBackPressed(){if(web.canGoBack())web.goBack();else {setEnabled(false);getOnBackPressedDispatcher().onBackPressed();}}});web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Bridge(),"TrailboundNative");
  WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();
  web.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return loader.shouldInterceptRequest(r.getUrl());}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(ORIGIN.equals(u.getScheme()+"://"+u.getHost())&&u.getPath().startsWith("/assets/"))return false;if(r.isForMainFrame()&&("https".equals(u.getScheme())||"http".equals(u.getScheme())))startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}});web.setWebChromeClient(new WebChromeClient(){
   public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);startActivityForResult(i,21);return true;}
   public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback callback){callback.invoke(origin,ORIGIN.equals(origin)&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED,false);}
  });web.loadUrl(ORIGIN+"/assets/index.html");
 }
 private void startTrack(String name){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){pendingName=name;requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},10);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){pendingName=name;requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11);return;}try{if(db.active()!=null)throw new IllegalStateException("Finish the active native track first");db.start(name);startForegroundService(new Intent(this,TrackingService.class));}catch(Exception e){db.finish();new AlertDialog.Builder(this).setMessage(e.getMessage()).setPositiveButton("OK",null).show();}}
 public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==10&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)startTrack(pendingName);else if(code==11){if(checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)startTrack(pendingName);else new AlertDialog.Builder(this).setMessage("Enable notifications for a visible recording indicator, then try again.").setPositiveButton("OK",null).show();}}
 public final class Bridge {
  @JavascriptInterface public String snapshot(){return db.snapshot();}
  @JavascriptInterface public void start(String name){runOnUiThread(()->startTrack(name==null?"Hike":name.substring(0,Math.min(200,name.length()))));}
  @JavascriptInterface public void resume(){runOnUiThread(()->{if(db.active()!=null)startForegroundService(new Intent(MainActivity.this,TrackingService.class));});}
  @JavascriptInterface public void stop(){runOnUiThread(()->{db.finish();stopService(new Intent(MainActivity.this,TrackingService.class));});}
  @JavascriptInterface public void saveDocument(String name,String data,String mime){if(data==null||data.length()>134217728)return;runOnUiThread(()->{if(pendingDocument!=null)return;pendingDocument=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(mime==null?"application/octet-stream":mime).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,22);});}
  @JavascriptInterface public void exportTracks(){runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"trailbound-native-backup.json");startActivityForResult(i,20);});}
 }
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==21&&fileCallback!=null){fileCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));fileCallback=null;return;}if(request==22){try{if(result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingDocument!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(pendingDocument.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}}catch(Exception e){new AlertDialog.Builder(this).setMessage("Save failed: "+e.getMessage()).setPositiveButton("OK",null).show();}finally{pendingDocument=null;}return;}if(request==20&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(db.snapshot().getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){new AlertDialog.Builder(this).setMessage("Export failed: "+e.getMessage()).setPositiveButton("OK",null).show();}}}
 protected void onDestroy(){if(fileCallback!=null)fileCallback.onReceiveValue(null);web.removeJavascriptInterface("TrailboundNative");web.destroy();db.close();super.onDestroy();}
}
